import numpy as np, os, json

N = 26
TOL = 1e-8

# Sources (exports at tol=1e-8)
NOESIS = {
    "name": "noesis_sota243",
    "boundary": "storage/noesis/exports/sota_243/active_boundary_tol1e8.csv",
    "pairs":    "storage/noesis/exports/sota_243/active_pairs_tol1e8.csv",
}
ALETHEIA = {
    "name": "aletheia_eval155",
    "boundary": "storage/Aletheia/exports/active_boundary_tol1e8.csv",
    "pairs":    "storage/Aletheia/exports/active_pairs_tol1e8.csv",
}
INQUIRE = {
    "name": "inquire_eval207",
    "boundary": "storage/Inquire/exports/active_boundary_tol1e8.csv",
    "pairs":    "storage/Inquire/exports/active_pairs_tol1e8.csv",
}
SCIENTIA = {
    "name": "scientia_latest",
    "boundary": "storage/Scientia/exports/active_boundary_tol1e8.csv",
    "pairs":    "storage/Scientia/exports/active_pairs_tol1e8.csv",
}
PEERS = [NOESIS, ALETHEIA, INQUIRE, SCIENTIA]

OUT_JSON = 'storage/noesis/nmap/consensus_n26_4lineage_sota243_tol1e8.json'
OUT_CSV  = 'storage/noesis/nmap/consensus_n26_4lineage_sota243_tol1e8.csv'

def load_latest():
    c = np.loadtxt('storage/noesis/latest_centers.txt').reshape(N, 2)
    r = np.loadtxt('storage/noesis/latest_radii.txt').reshape(N,)
    return np.array(c, float), np.array(r, float)

def map_kind(k):
    k = k.strip()
    return {'xmin': 'xL', 'xmax': 'xR', 'ymin': 'yB', 'ymax': 'yT'}.get(k, k)

def read_boundary_csv(path):
    S = set()
    with open(path, 'r') as f:
        header = True
        for line in f:
            line = line.strip()
            if not line: continue
            if header:
                header = False
                continue
            parts = [p.strip() for p in line.split(',')]
            i = int(parts[0])
            kind = map_kind(parts[1])
            S.add((i, kind))
    return S

def read_pairs_csv(path):
    S = set()
    with open(path, 'r') as f:
        header = True
        for line in f:
            line = line.strip()
            if not line: continue
            if header:
                header = False
                continue
            parts = [p.strip() for p in line.split(',')]
            i = int(parts[0]); j = int(parts[1])
            if i > j: i, j = j, i
            S.add((i, j))
    return S

def consensus_sets(sets):
    inter = None
    uni = set()
    for s in sets:
        uni |= s
        inter = s if inter is None else (inter & s)
    return inter if inter is not None else set(), uni

def write_diff_csv(base_set, other_set, path):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    only_base = sorted(list(base_set - other_set))
    only_other = sorted(list(other_set - base_set))
    with open(path, 'w') as f:
        f.write("side,i,kind\n")
        for (i, kind) in only_base:
            f.write(f"only_noesis,{i},{kind}\n")
        for (i, kind) in only_other:
            f.write(f"only_peer,{i},{kind}\n")

def jaccard(A, B):
    inter = len(A & B)
    uni = len(A | B)
    return inter, uni, (inter / uni if uni > 0 else 1.0)

def construct_packing():
    # Read all sets
    B_sets = {}
    P_sets = {}
    for src in PEERS:
        B_sets[src["name"]] = read_boundary_csv(src["boundary"])
        P_sets[src["name"]] = read_pairs_csv(src["pairs"])

    # Consensus and union
    B_inter, B_union = consensus_sets(list(B_sets.values()))
    P_inter, P_union = consensus_sets(list(P_sets.values()))

    # Sizes per lineage
    sizes = {
        "boundary": {k: len(v) for k, v in B_sets.items()},
        "pairs":    {k: len(v) for k, v in P_sets.items()},
    }

    # Pairwise Jaccards (pairs only)
    pairwise = {}
    keys = list(P_sets.keys())
    for i in range(len(keys)):
        for j in range(i+1, len(keys)):
            ki, kj = keys[i], keys[j]
            pi, pu, pj = jaccard(P_sets[ki], P_sets[kj])
            pairwise[f"{ki}__{kj}"] = {"intersection": pi, "union": pu, "jaccard": pj}

    # Boundary diffs vs Noesis
    diffs_dir = 'storage/noesis/nmap/consensus_diffs'
    write_diff_csv(B_sets["noesis_sota243"], B_sets["aletheia_eval155"], f"{diffs_dir}/boundary_diff_aletheia_vs_noesis.csv")
    write_diff_csv(B_sets["noesis_sota243"], B_sets["inquire_eval207"],  f"{diffs_dir}/boundary_diff_inquire_vs_noesis.csv")
    write_diff_csv(B_sets["noesis_sota243"], B_sets["scientia_latest"],  f"{diffs_dir}/boundary_diff_scientia_vs_noesis.csv")

    os.makedirs('storage/noesis/nmap', exist_ok=True)
    data = {
        "n": 26,
        "tolerance": "1e-8",
        "lineages": [src["name"] for src in PEERS],
        "paths": {src["name"]: {"boundary": src["boundary"], "pairs": src["pairs"]} for src in PEERS},
        "boundary": {
            "intersection_size": len(B_inter),
            "union_size": len(B_union),
            "sizes": sizes["boundary"]
        },
        "pairs": {
            "intersection_size": len(P_inter),
            "union_size": len(P_union),
            "sizes": sizes["pairs"]
        },
        "pairwise_pairs_jaccard": pairwise,
        "diffs": {
            "dir": diffs_dir,
            "files": [
                f"{diffs_dir}/boundary_diff_aletheia_vs_noesis.csv",
                f"{diffs_dir}/boundary_diff_inquire_vs_noesis.csv",
                f"{diffs_dir}/boundary_diff_scientia_vs_noesis.csv"
            ]
        }
    }
    with open(OUT_JSON, 'w') as f:
        json.dump(data, f, indent=2)

    with open(OUT_CSV, 'w') as f:
        f.write("section,metric,value\n")
        f.write(f"boundary,intersection_size,{len(B_inter)}\n")
        f.write(f"boundary,union_size,{len(B_union)}\n")
        for k, v in sizes["boundary"].items():
            f.write(f"boundary,size_{k},{v}\n")
        f.write(f"pairs,intersection_size,{len(P_inter)}\n")
        f.write(f"pairs,union_size,{len(P_union)}\n")
        for k, v in sizes["pairs"].items():
            f.write(f"pairs,size_{k},{v}\n")
        for key, val in pairwise.items():
            f.write(f"pairs_jaccard,{key},{val['jaccard']}\n")

    # Return unchanged current SOTA packing
    c, r = load_latest()
    return np.array(c, float), np.array(r, float)
